package cz.mh.rallye.rallye_backend.races.application;
import java.time.*;import java.util.*;import java.nio.file.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
import org.springframework.transaction.*;import org.springframework.transaction.support.SimpleTransactionStatus;
import cz.mh.rallye.rallye_backend.races.persistence.EventStore;
import cz.mh.rallye.rallye_backend.templates.persistence.TemplateStore;
import cz.mh.rallye.rallye_backend.templates.application.*;
import cz.mh.rallye.rallye_backend.templates.domain.StageConfiguration;
import cz.mh.rallye.rallye_backend.identity.application.*;
import cz.mh.rallye.rallye_backend.identity.persistence.*;
import cz.mh.rallye.rallye_backend.shared.persistence.CommandStore;
import cz.mh.rallye.rallye_backend.audit.application.AuditService;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class EventServiceTest {
 @TempDir Path root;EventService service;TemplateImageFiles source;EventFiles files;
 final EventStore events=mock(EventStore.class);final TemplateStore templates=mock(TemplateStore.class);final AdminStore roles=mock(AdminStore.class);final AccountStore accounts=mock(AccountStore.class);final CommandStore commands=mock(CommandStore.class);final AuditService audit=mock(AuditService.class);final PlatformTransactionManager manager=mock(PlatformTransactionManager.class);
 final UUID id=UUID.randomUUID(),key=UUID.randomUUID();final Instant now=Instant.parse("2026-10-28T10:00:00Z");
 final AuthService.Principal actor=new AuthService.Principal(UUID.randomUUID(),UUID.randomUUID(),false);
 EventService.Input input(){return new EventService.Input("Event",null,null,null);}
 @BeforeEach void setup(){source=new TemplateImageFiles(root.resolve("source").toString());files=new EventFiles(root.resolve("events").toString());service=new EventService(events,templates,source,files,new TemplateFileContent(102400,10485760),roles,accounts,commands,audit,Clock.fixed(now,ZoneOffset.UTC),manager);when(manager.getTransaction(any())).thenAnswer(i->new SimpleTransactionStatus());when(roles.activeVerified(actor.accountId())).thenReturn(true);when(roles.administrator(actor.accountId())).thenReturn(true);when(accounts.isActiveSession(actor.sessionId(),actor.accountId(),now)).thenReturn(true);when(templates.lock(id)).thenReturn(new TemplateStore.Template(id,"Source",null,-2,"READY",4,now,now));var empty=StageConfiguration.empty();var cfg=new StageConfiguration(new StageConfiguration.Gps(true,1d,1d,50d,0L,0L),empty.code(),empty.timePenalty(),empty.delayed());when(templates.stages(id)).thenReturn(List.of(new TemplateStore.Stage(UUID.randomUUID(),id,1,"Station",0L,0L,"Text",cfg)));}
 @Test void readyCopiesStagesAndAuditsAndUsesLedger(){var created=service.create(actor,id,4,key,input());assertEquals(0,created.version());verify(events).copyStage(any(),any(),eq(created.id()),eq("Text"));verify(audit).race(actor.accountId(),AuditService.Event.RACE_EVENT_CREATED,created.id(),id,4);verify(commands).save(eq(actor.accountId()),eq(key),eq(created.id()),eq("RACE_EVENT_CREATE"),anyString(),anyString(),eq(now));}
 @Test void draftIsRejected(){when(templates.lock(id)).thenReturn(new TemplateStore.Template(id,"Source",null,0,"DRAFT",4,now,now));assertEquals("TEMPLATE_NOT_READY",assertThrows(AuthFailure.class,()->service.create(actor,id,4,key,input())).code());verifyNoInteractions(events,audit);}
 @Test void readyWithMissingReferenceIsRejected(){var s=templates.stages(id).getFirst();when(templates.stages(id)).thenReturn(List.of(new TemplateStore.Stage(s.id(),id,1,s.name(),0L,0L,"![Missing](absent.png)",s.configuration())));assertEquals("TEMPLATE_NOT_READY",assertThrows(AuthFailure.class,()->service.create(actor,id,4,key,input())).code());verifyNoInteractions(events,audit);}
 @Test void missingAndStaleSourcesAreRejected(){when(templates.lock(id)).thenReturn(null);assertEquals(404,assertThrows(AuthFailure.class,()->service.create(actor,id,4,key,input())).status());reset(templates);when(templates.lock(id)).thenReturn(new TemplateStore.Template(id,"Source",null,0,"READY",5,now,now));assertEquals("TEMPLATE_VERSION_CONFLICT",assertThrows(AuthFailure.class,()->service.create(actor,id,4,key,input())).code());verifyNoInteractions(events,audit);}
 @Test void replayPrecedesSourceVersionAndHasNoNewAudit(){UUID event=UUID.randomUUID();when(commands.replay(eq(actor.accountId()),eq(key),eq("RACE_EVENT_CREATE"),anyString(),eq(now))).thenReturn("{\"id\":\""+event+"\",\"version\":0}");assertEquals(event,service.create(actor,id,4,key,input()).id());verifyNoInteractions(templates,events,audit);}
 @Test void changedRequestIsConflictBeforeSourceChecks(){when(commands.replay(any(),any(),anyString(),anyString(),any())).thenThrow(new AuthFailure(409,"IDEMPOTENCY_CONFLICT"));assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(AuthFailure.class,()->service.create(actor,id,4,key,input())).code());verifyNoInteractions(templates,events,audit);}
 @Test void authorizationIsRepeatedAtMutation(){when(roles.administrator(actor.accountId())).thenReturn(true,false);assertEquals(403,assertThrows(AuthFailure.class,()->service.create(actor,id,4,key,input())).status());verifyNoInteractions(templates,events,audit);}
 @Test void nonAdminAndExpiredSessionCannotRead(){when(roles.administrator(actor.accountId())).thenReturn(false);assertEquals(403,assertThrows(AuthFailure.class,()->service.detail(actor,id)).status());when(accounts.isActiveSession(any(),any(),any())).thenReturn(false);assertEquals(401,assertThrows(AuthFailure.class,()->service.detail(actor,id)).status());verifyNoInteractions(events);}
 @Test void invalidInputsAndPageAreRejected(){for(var input:List.of(new EventService.Input(" ",null,null,null),new EventService.Input("x".repeat(101),null,null,null),new EventService.Input("Event","x".repeat(2001),null,null),new EventService.Input("Event",null,now,now))){assertThrows(AuthFailure.class,()->service.create(actor,id,4,key,input));}assertThrows(AuthFailure.class,()->service.list(actor,null,-1,10));assertThrows(AuthFailure.class,()->service.list(actor,null,0,101));verifyNoInteractions(events,audit);}
 EventStore.Event row(){return new EventStore.Event(id,UUID.randomUUID(),4,"Event",null,-2,"PLANNED",null,null,3,now,now);}
 @Test void noOpDoesNotUpdateOrAudit(){var e=row();when(events.lock(id)).thenReturn(e);assertEquals(3,service.update(actor,id,3,input()).version());verify(events,never()).update(any(),any(),any(),any(),any(),any());verifyNoInteractions(audit);}
 @Test void editChecksVersionAndRejectsStateChanges(){var e=row();when(events.lock(id)).thenReturn(e);assertEquals("RACE_EVENT_VERSION_CONFLICT",assertThrows(AuthFailure.class,()->service.update(actor,id,2,input())).code());verifyNoInteractions(audit);}
 @Test void auditFailureRollsBackTransactionAndRemovesCopiedBytes()throws Exception{byte[] data=cz.mh.rallye.rallye_backend.crews.PhotoFilesTest.image("png",2,2);source.files.exclusive(()->{source.write(id,"map.png",data);return null;});when(templates.images(id)).thenReturn(List.of(new TemplateStore.Image(UUID.randomUUID(),id,"map.png","MAP.PNG","image/png",data.length,2,2,now,false)));doThrow(new IllegalStateException("Injected")).when(audit).race(any(),any(),any(),any(),anyLong());assertThrows(IllegalStateException.class,()->service.create(actor,id,4,key,input()));try(var all=Files.walk(root.resolve("events"))){assertEquals(0,all.filter(p->p.toString().endsWith(".png")).count());}verify(manager).rollback(any());verify(commands,never()).save(any(),any(),any(),any(),any(),any(),any());assertArrayEquals(data,source.read(id,"map.png"));}
 @Test void sourceAndEventPathsAreSeparateEvenForSameId(){source.files.exclusive(()->{source.write(id,"guide.md","source".getBytes());return null;});files.storage.files.exclusive(()->{files.storage.write(id,"guide.md","event".getBytes());return null;});assertEquals("source",new String(source.read(id,"guide.md")));assertEquals("event",new String(files.storage.read(id,"guide.md")));}
 @Test void identicalStorageRootsAreRejected(){assertThrows(IllegalArgumentException.class,()->new EventService(events,templates,source,new EventFiles(root.resolve("source").toString()),new TemplateFileContent(102400,10485760),roles,accounts,commands,audit,Clock.fixed(now,ZoneOffset.UTC),manager));}
 @Test void missingMetadataFileAndCrossEventNamesAre404(){when(events.lock(id)).thenReturn(row());assertEquals("RACE_EVENT_FILE_NOT_FOUND",assertThrows(AuthFailure.class,()->service.file(actor,id,"missing.png")).code());assertThrows(AuthFailure.class,()->service.file(actor,id,"../file.png"));}

 @Test void invalidSourceNameKeyCannotCreateAnInconsistentLibrary()throws Exception{byte[] data=cz.mh.rallye.rallye_backend.crews.PhotoFilesTest.image("png",2,2);source.files.exclusive(()->{source.write(id,"map.png",data);return null;});when(templates.images(id)).thenReturn(List.of(new TemplateStore.Image(UUID.randomUUID(),id,"map.png","WRONG.PNG","image/png",data.length,2,2,now,false)));assertEquals("RACE_EVENT_SNAPSHOT_UNAVAILABLE",assertThrows(AuthFailure.class,()->service.create(actor,id,4,key,input())).code());verify(events,never()).file(any(),any(),any(),any(),any(),any());verifyNoInteractions(audit);}

}
